"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6712],{33868:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"WorkbenchGuiController","desc":"Drives the Studio-authored `WorkbenchGui`. Opens via a placed Workbench\\nstation\'s ProximityPrompt (CollectionService `WorkbenchStation`), builds the\\nrecipe grid from `WorkbenchConfig`, fills the detail pane on selection, sends\\n`ReqCraft` on Accept, and wires Stash/Move via `PlaceableActions`. Greys\\nrecipes the player can\'t afford or that are gated by a locked Tech node;\\nrepaints live on Backpack and Tech-unlock changes. The recipe grid is\\nfiltered by category; the (future) custom dropdown drives the filter by\\nfiring `Signals.RequestWorkbenchCategory` \u2014 no dropdown UI exists yet.","realm":["Client"],"source":{"line":15,"path":"src/StarterPlayer/StarterPlayerScripts/WorkbenchGuiController.client.luau"}}')}}]);